GO.ga4_siusti:
function siusti( $order_id ) {
		static $done = array();
		$order_id = (int) $order_id;
		if ( ! $order_id || isset( $done[ $order_id ] ) ) { return; }
		$order = wc_get_order( $order_id );
		if ( ! $order || ! in_array( $order->get_status(), array( 'processing', 'on-hold', 'completed' ), true ) ) { return; }
		if ( $order->get_meta( '_ps_ga4_mp_at' ) ) { return; }
		$done[ $order_id ] = 1;
		if ( ! self::prod() ) { $order->update_meta_data( '_ps_ga4_mp_kodas', 'dev-nesiusta' ); $order->save(); return; }
		$secret = self::secret();
		if ( '' === $secret ) { $order->update_meta_data( '_ps_ga4_mp_kodas', 'laukia-rakto' ); $order->save(); return; }
		$body = self::payload( $order );
		$r = wp_remote_post( 'https://www.google-analytics.com/mp/collect?measurement_id=' . self::MID . '&api_secret=' . rawurlencode( $secret ), array(
			'timeout' => 8, 'headers' => array( 'Content-Type' => 'application/json' ), 'body' => wp_json_encode( $body ) ) );
		$code = is_wp_error( $r ) ? 'err:' . $r->get_error_message() : (string) wp_remote_retrieve_response_code( $r );
		if ( '204' === $code ) { $order->update_meta_data( '_ps_ga4_mp_at', current_time( 'mysql', true ) ); }
		$order->update_meta_data( '_ps_ga4_mp_kodas', $code );
		$order->update_meta_data( '_ps_ga4_mp_cid', $body['client_id'] );
		$order->save();
	}

