GO.ga4_payload:
function payload( $order ) {
		$items = array();
		foreach ( $order->get_items( 'line_item' ) as $it ) {
			$p   = $it->get_product();
			$pid = $p ? ( $p->get_parent_id() ?: $p->get_id() ) : (int) $it->get_product_id();
			$qty = max( 1, (int) $it->get_quantity() );
			$row = array(
				'item_id'   => $p && $p->get_sku() ? (string) $p->get_sku() : (string) $pid,
				'item_name' => wp_strip_all_tags( $it->get_name() ),
				'quantity'  => $qty,
				'price'     => round( ( (float) $it->get_total() + (float) $it->get_total_tax() ) / $qty, 2 ),
			);
			if ( function_exists( 'petshop_gtm_brand' ) ) { $b = petshop_gtm_brand( $pid ); if ( $b ) { $row['item_brand'] = $b; } }
			$cats = get_the_terms( $pid, 'product_cat' );
			if ( $cats && ! is_wp_error( $cats ) ) { $row['item_category'] = $cats[0]->name; }
			$items[] = $row;
		}
		$cid = (string) $order->get_meta( '_ps_ga_cid' );
		$sut = (string) $order->get_meta( '_ps_ga_sutikimas' );
		if ( '' === $cid ) { $cid = 'ps.' . sprintf( '%u', crc32( 'ps-' . $order->get_id() . '-' . $order->get_billing_email() ) ) . '.' . $order->get_date_created()->getTimestamp(); }
		$params = array(
			'transaction_id'       => (string) $order->get_id(),
			'value'                => round( (float) $order->get_total(), 2 ),
			'tax'                  => round( (float) $order->get_total_tax(), 2 ),
			'shipping'             => round( (float) $order->get_shipping_total() + (float) $order->get_shipping_tax(), 2 ),
			'currency'             => $order->get_currency() ?: 'EUR',
			'coupon'               => implode( ',', $order->get_coupon_codes() ),
			'payment_type'         => (string) $order->get_payment_method(),
			'ps_saltinis'          => 'serveris',
			'engagement_time_msec' => 1,
			'items'                => $items,
		);
		if ( '' === $params['coupon'] ) { unset( $params['coupon'] ); }
		$sid = (string) $order->get_meta( '_ps_ga_sid' );
		if ( '' !== $sid ) { $params['session_id'] = $sid; }
		$body = array(
			'client_id'            => $cid,
			'non_personalized_ads' => ( strpos( $sut, 'M' ) === false ),
			'events'               => array( array( 'name' => 'purchase', 'params' => $params ) ),
		);
		/* timestamp_micros — leidžiama iki 72 val. atgal; užsakymo sukūrimo laikas sujungia su sesija */
		$ts = $order->get_date_created() ? $order->get_date_created()->getTimestamp() : time();
		if ( time() - $ts < 71 * HOUR_IN_SECONDS ) { $body['timestamp_micros'] = $ts * 1000000; }
		return $body;
	}

